export async function seedDioceseNyIntercession(): Promise<number> {
  // Upsert the feed itself (platform-owned). Keep the presentation fields and
  // public visibility fresh on every boot; only PROMOTE a never-launched draft
  // to live so a deliberate admin "pause" is never silently undone (mirrors the
  // phoebe-climate seed rule).
  await db
    .insert(prayerFeedsTable)
    .values({
      slug: FEED.slug,
      title: FEED.title,
      tagline: FEED.tagline,
      coverEmoji: FEED.coverEmoji,
      timezone: FEED.timezone,
      state: "live",
      visibility: "public",
      kind: "general",
      creatorUserId: null,
    })
    .onConflictDoUpdate({
      target: prayerFeedsTable.slug,
      set: {
        title: FEED.title,
        tagline: FEED.tagline,
        coverEmoji: FEED.coverEmoji,
        timezone: FEED.timezone,
        visibility: "public",
        updatedAt: new Date(),
      },
    });
  // Promote draft -> live, and force platform ownership, without touching a
  // deliberate 'paused'.
  await db
    .update(prayerFeedsTable)
    .set({ state: "live" })
    .where(and(eq(prayerFeedsTable.slug, FEED.slug), eq(prayerFeedsTable.state, "draft")));
  await db
    .update(prayerFeedsTable)
    .set({ creatorUserId: null })
    .where(eq(prayerFeedsTable.slug, FEED.slug));

  const [feed] = await db
    .select({ id: prayerFeedsTable.id })
    .from(prayerFeedsTable)
    .where(eq(prayerFeedsTable.slug, FEED.slug));
  if (!feed) return 0;

  // This is a DATE-PROGRAMMED feed: one intention per calendar day, in
  // prayer_feed_entries (the "what they have that day" model). The subscriber
  // surfaces don't read this table directly — lib/feedDailyPromotion mirrors
  // each day's entry into the feed's live intercession moment — but this is the
  // editable source of truth (same store the feed-manage editor writes).
  const now = new Date();
  const rows = ENTRIES.map((e) => ({
    feedId: feed.id,
    entryDate: e.d,
    slot: 1,
    title: e.t,
    body: BODY,
    source: "custom",
    state: "published",
    publishedAt: now,
  }));

  // Upsert in chunks — keep each day's title fresh (so a future correction
  // propagates) while leaving pray counts and ids intact.
  const CHUNK = 100;
  for (let i = 0; i < rows.length; i += CHUNK) {
    await db
      .insert(prayerFeedEntriesTable)
      .values(rows.slice(i, i + CHUNK))
      .onConflictDoUpdate({
        target: [
          prayerFeedEntriesTable.feedId,
          prayerFeedEntriesTable.entryDate,
          prayerFeedEntriesTable.slot,
        ],
        set: {
          title: sql`excluded.title`,
          body: sql`excluded.body`,
          state: sql`excluded.state`,
          publishedAt: sql`excluded.published_at`,
          updatedAt: now,
        },
      });
  }

  // Clean up the previous (rotating-moments) seed: the 365 per-day `dny-<date>`
  // moments are superseded by the single promoted "today" moment, so archive
  // them out of every subscriber surface. (Archive, not delete, in case any
  // already carry prayer check-ins.)
  await db
    .update(sharedMomentsTable)
    .set({ state: "archived" })
    .where(and(
      eq(sharedMomentsTable.prayerFeedId, feed.id),
      sql`${sharedMomentsTable.momentToken} LIKE 'dny-%'`,
    ));

  return rows.length;
}
